entries[56453] = { ["name"] = "Sichern und Laden", ["text"] = "Sofort 22 sek. Abklingzeit\nWird ein Ziel durch Eure Eiskälte- oder Frostfalle oder Eure Fähigkeit 'Eiskältepfeil' gefangen, besteht eine Chance; oder erleidet es durch den regelmäßigen Effekt Eurer Feuerbrandfalle, Sprengfalle oder Eurer Fähigkeit 'Schwarzer Pfeil' Schaden, besteht eine Chance, dass Eure nächsten 2 Anwendungen von 'Arkaner Schuss' oder 'Explosivschuss' keine Abklingzeit auslösen, kein Mana kosten und keine Munition verbrauchen. Dieser Effekt hat eine Abklingzeit von 22 Sek." }
entries[56454] = { ["name"] = "Gefrorenes Belagerungsgeschoss" }
entries[56458] = { ["name"] = "Aufladen", ["text"] = "Unbegrenzte Reichweite\nSofort\nLädt das Ziel mit Elektrizität auf." }
entries[56459] = { ["name"] = "Spitzhammer", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nKobaltbarren (5)\n\"Kann als Spitzhacke oder Schmiedehammer verwendet werden.\"" }
entries[56460] = { ["name"] = "Kobaltsplitterbombe", ["text"] = "Wirken in 2 sek.\nTools:\nBogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nEine Hand voll Kobaltbolzen (2), Unberechenbarer Sprengauslöser\n(3)\nBenötigt Ingenieurskunst\n(330)\nBenutzen: Fügt 750 to 1000 Feuerschaden zu und macht Ziele 3 sec lang in einem Radius von 3 Metern handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen. (1 Min Abklingzeit)" }
entries[56461] = { ["name"] = "Klingenhacke", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nKobaltbarren (5)\n\"Kann als Spitzhacke oder Kürschnermesser verwendet werden.\"" }
entries[56462] = { ["name"] = "Gnomisches Armeemesser", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (10), Kürschnermesser , Spitzhacke , Schmiedehammer\nBenutzen: Ein Großmeister der Ingenieurskunst kann die Batterien des Messers überladen, um zu versuchen, einen toten Spieler ins Leben zurückzurufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)\n\"Beinhaltet einen gyromatischen Mikroregler, einen Bogenlichtschraubenschlüssel, Feuerstein und Zunder, einen Schmiedehammer, eine Spitzhacke und ein Kürschnermesser.\"" }
entries[56463] = { ["name"] = "Explosiver Lockvogel", ["text"] = "Wirken in 2 sek.\nTools:\nBogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nFroststoff , Unberechenbarer Sprengauslöser (3)\n(5)\nBenötigt Ingenieurskunst\n(350)\nBenutzen: Beschwört einen Lockvogel, der explodiert, wenn er angegriffen wird, und Gegnern 1440 to 2160 körperlichen Schaden zufügt. Hält 3 Min. lang an oder bis er explodiert. (2 Min Abklingzeit)\n\"Warnhinweis: Kann vorzeitig explodieren, wenn elektromagnetischem Puls ausgesetzt.\"" }
entries[56464] = { ["name"] = "Überladener Kondensator", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nKobaltbarren (4), Kristallisierte Erde" }
entries[56465] = { ["name"] = "Mechanische Schneebrille", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (8), Boreanisches Leder (2), Äonenschatten\nMechanische Schneebrille\nWird beim Anlegen gebunden\nKopf Stoff\n225 Rüstung\n<Zufällige Verzauberung>\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst\n(400)\nAnlegen: Vor Kälte geschützt. Euer Frostwiderstand ist um 20 erhöht." }
entries[56466] = { ["name"] = "Überschallbooster", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (4), Eine Hand voll Kobaltbolzen (2)\nÜberschallbooster\nWird beim Anlegen gebunden\nSchmuck\n+81 Ausdauer\nBenötigt Ingenieurskunst\n(390)\nAnlegen: In manchen Fällen schärft der Lärm von Nahkämpfen Euer Schallbewusstsein und erhöht 10 sec lang Eure Angriffskraft um 430. Dieser Effekt kann pro Minute nur einmal auftreten. (Procchance: 35%, 50s Abklingzeit)" }
entries[56467] = { ["name"] = "Lärmmaschine", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer\nReagenzien:\nFroststahlröhre (2), Überladener Kondensator (2), Eine Hand voll Kobaltbolzen (8)\nLärmmaschine\nWird beim Anlegen gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(390)\nAnlegen: Erhöht die Zaubermacht um 63.\nAnlegen: Nahkampfangriffe auf Euch haben eine Chance, einen Schallschild zu beschwören, der 1100 Schaden absorbiert. Dieser Effekt kann nur einmal pro Minute auftreten. (Procchance: 50%, 50s Abklingzeit)" }
entries[56468] = { ["name"] = "Kiste voller Bomben", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nSaronitbarren (5), Unberechenbarer Sprengauslöser\n\"Beinhaltet Saronitbomben. Jede Menge Saronitbomben.\"\n<Zum Öffnen rechtsklicken>" }
entries[56469] = { ["name"] = "Gnomischer Blitzgenerator", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer\nReagenzien:\nTitanbarren (2), Saronitbarren (8), Äonenwasser (2), Äonenluft (2)\nGnomischer Blitzgenerator\nWird beim Aufheben gebunden\nSchmuck\nBenötigt Ingenieurskunst\n(425)\nAnlegen: Erhöht die kritische Trefferwertung um 84.\nBenutzen: Erzeugt einen Blitzstrahl, der einen Feind für 1530 to 1870 Naturschaden trifft. Das ganze Gehäuse des Geräts ist aus Metall... (1 Min Abklingzeit)\n\"Garantiert sicher!\"" }
entries[56470] = { ["name"] = "Sonnenzielfernrohr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer\nReagenzien:\nFroststahlröhre , Sonnenkristall , Herbstglimmer\nSonnenzielfernrohr\n70\nBenutzen: Verbindet dauerhaft ein Zielfernrohr mit dem Bogen oder der Schusswaffe und erhöht damit die Distanztempowertung um 40.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[56471] = { ["name"] = "Froststahlröhre", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nKobaltbarren (8), Kristallisiertes Wasser" }
entries[56472] = { ["name"] = "MOLL-E", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (8), Äonenluft (8)\nMOLL-E\nSpielzeug\nBenötigt Ingenieurskunst\n(425)\nBenutzen: Erstellt 10 min lang einen tragbaren Briefkasten. MOLL-E wird nach seiner Nutzung nicht zerstört. (2 Std. Abklingzeit)\n\"Mobiler optimierter Liebesbrief- und Lieferungsextraktor\"" }
entries[56473] = { ["name"] = "Gnomische Röntgenbrille", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer\nReagenzien:\nTitanbarren (6), Traumsplitter (2), Eine Hand voll Kobaltbolzen (2)\nGnomische Röntgenbrille\nWird beim Aufheben gebunden\nSpielzeug\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gnomeningenieur\nBenutzen: Ermöglicht es Euch, Spieler ohne Kleidung und Rüstung zu sehen. (3 Sek. Abklingzeit)" }
entries[56474] = { ["name"] = "Mammutschneider", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nSaronitbarren , Unberechenbarer Sprengauslöser\nMammutschneider\n(1000)Munition Kugel\nVerursacht 67.5 zusätzlichen Schaden pro Sekunde.\n72" }
entries[56475] = { ["name"] = "Messerscharfe Saronitpfeile", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer , Gyromatischer Mikroregler\nReagenzien:\nSaronitbarren (2)\nMesserscharfe Saronitpfeile\n(1000)Munition Pfeil\nVerursacht 67.5 zusätzlichen Schaden pro Sekunde.\n72" }
entries[56476] = { ["name"] = "Einspritzerset: Heiltrank", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (12), Eine Hand voll Kobaltbolzen (2)\n(8)\nBenutzen: Wandelt 20 runenverzierte Heiltränke zu einer kompakten Einspritzung.\n\"Mit Vorsicht verwenden.\"" }
entries[56477] = { ["name"] = "Einspritzerset: Manatrank", ["text"] = "Wirken in 2 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (12), Kristallisiertes Wasser (2)\n(8)\nBenutzen: Wandelt 20 runenverzierte Manatränke zu einer kompakten Einspritzung.\n\"Ausfallsicher.\"" }
entries[56478] = { ["name"] = "Herzsucherzielfernrohr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer\nReagenzien:\nSaronitbarren (10), Zwielichtopal (2)\nHerzsucherzielfernrohr\n70\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit einem Bogen oder einer Schusswaffe und erhöht die kritische Distanztrefferwertung dieser Waffe um 40.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[56479] = { ["name"] = "Plattenverstärkte Gefechtsschrotflinte", ["text"] = "Wirken in 50 sek.\nTools:\nSchmiedehammer\nReagenzien:\nTitanbarren (10), Saronitbarren (20), Äonenluft (15), Äonenwasser (15), Gefrorene Kugel , Schäftung aus Walnussholz\nPlattenverstärkte Gefechtsschrotflinte\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n181 - 337 Schaden Tempo 2.00\n(129.50 Schaden pro Sekunde)\n+42 Ausdauer\n\nBlauer Sockel\nSockelbonus: +6 Ausdauer\n\nHaltbarkeit 90 / 90\n80\nAnlegen: Erhöht die Verteidigungswertung um 21.\nAnlegen: Erhöht die Trefferwertung um 18." }
entries[56480] = { ["name"] = "Aufgerüstete Titanbrille", ["text"] = "Wirken in 50 sek.\nTools:\nSchmiedehammer\nReagenzien:\nTitanbarren (8), Schweres boreanisches Leder (4), Himmelssaphir (2), Äonenerde (4), Gefrorene Kugel\nAufgerüstete Titanbrille\nWird beim Aufheben gebunden\nKopf Platte\n1821 Rüstung\n+73 Stärke\n+111 Ausdauer\n\nMetasockel\nGelber Sockel\nSockelbonus: +8 Waffenkundewertung\n\nHaltbarkeit 100 / 100\n72\nBenötigt Ingenieurskunst\n(400)\nAnlegen: Erhöht die Verteidigungswertung um 60.\nAnlegen: Erhöht Eure Waffenkundewertung um 43.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen. (3 Sek. Abklingzeit)" }
entries[56481] = { ["name"] = "Schwachstellenspektralisierer", ["text"] = "Wirken in 50 sek.\nTools:\nSchmiedehammer\nReagenzien:\nTitanbarren (8), Schweres boreanisches Leder (4), Scharlachrubin (2), Äonenluft (4), Gefrorene Kugel\nSchwachstellenspektralisierer\nWird beim Aufheben gebunden\nKopf Leder\n458 Rüstung\n+73 Beweglichkeit\n+90 Ausdauer\n\nMetasockel\nGelber Sockel\nSockelbonus: +8 Kritische Trefferwertung\n\nHaltbarkeit 70 / 70\n72\nBenötigt Ingenieurskunst\n(400)\nAnlegen: Erhöht die kritische Trefferwertung um 43.\nAnlegen: Erhöht die Angriffskraft um 148.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen. (3 Sek. Abklingzeit)" }
